import React from 'react';
import { v4 as uuid } from 'uuid';
import classNames from 'classnames';

import './index.less';

export interface SwitchProps {
  /**
   * Unique id not give to other switches in the form
   */
  id?: string;
  /**
   * boolean for current value
   */
  value?: boolean;
  /**
   * on change func
   */
  onChange?: (value: boolean) => void;
  /**
   * Sets component root css class
   */
  className?: string;
  /**
   * Label to show next to the switch
   */
  label?: string;
  /**
   * True for the component to be disabled
   */
  disabled?: boolean;
}

const defaultProps: SwitchProps = {
  id: uuid(),
  className: '',
  label: '',
  onChange: () => {},
  disabled: false,
  value: false,
};

export const Switch: React.FC<SwitchProps> = (props = {}) => {
  const { id, className, label, onChange, disabled, value } = {
    ...defaultProps,
    ...props,
  };

  return (
    <div className={classNames('switch', className)}>
      <input
        id={id}
        type="checkbox"
        checked={value}
        disabled={disabled}
        onChange={(event) => onChange?.(event?.target?.checked)}
      />
      <label htmlFor={id}> </label>
      <label htmlFor={id} className="switch-text-label">
        {label}
      </label>
    </div>
  );
};
